\label{df:pairwise_Lip}
A graph signal $\x$ with unit norm is~\emph{pairwise Lipschitz smooth} with parameter $C$ when it satisfies
\begin{equation*}
	| x_i - x_j |   \ \leq \  C \ d(v_i, v_j),~{\rm for~all~} i,j = 0, 1, \ldots, N-1,
\end{equation*}
with $d(v_i, v_j)$ the distance between the $i$th and the $j$th nodes.

\label{df:polynomial_sig}
A graph signal $\x$ is polynomial with degree $K$ when
\begin{equation*}
	\x \ = \  \D_{\rm poly(K)}  \a \ = \ \begin{bmatrix}
	{\bf 1}  &  \D^{(1)}  & \D^{(2)}  &  \ldots &  \D^{(K)} 
	\end{bmatrix} 
	\a \in \ensuremath{\mathbb{R}}^N,
\end{equation*}
where $\a \in \ensuremath{\mathbb{R}}^{KN+1}$ and $\D_{\rm poly(K)} $ is a graph polynomial dictionary with $\D^{(k)}_{i,j} = d^k(v_i, v_j)$. Denote this class by $\PL(K)$.

 ({\bf Graph polynomial dictionary represents the pairwise Lipschiz smooth signals})
\label{thm:BLvsGS}
$\PL(1)$ is a subset of the pairwise Lipschitz smooth with some parameter $C$.

A graph signal $\x$ is bandlimited with respect to a graph Fourier basis $\Vm$ with bandwidth $K$ when
\begin{equation*}
	\x = \Vm_{(K)} \a,
\end{equation*}
where $\a \in \ensuremath{\mathbb{R}}^{K}$ and $\Vm_{(K)}$ is a submatrix containing the first $K$ columns of $\Vm$. Denote this class by $\BL_{\Vm}(K)$~\cite{ChenVSK:15}.

 ({\bf The graph Fourier basis of the graph Laplacian represents the total Lipschiz smooth signals})
\label{thm:BLvsGS}
For any $K \in \{1, \cdots, N \}$, $\BL_{\Vm_{\LL}}(K)$ is a subset of the total Lipschitz smooth with parameter $C$, when $C \geq \lambda^{(\LL)}_k$.

({\bf The graph Fourier basis of the transition matrix represents the local normalized neighboring smooth signals})
\label{thm:LNNS}
For any $K \in \{1, \cdots, N \}$, $\BL_{\Vm_{\Pj}}(K)$ is a subset of the local normalized neighboring smooth with parameter $C$, when $C \geq  (1 - \lambda^{(\Pj)}_{K})^2$.

 ({\bf The graph Fourier basis of the adjacency matrix represents the global normalized neighboring smooth signals})
\label{thm:GNNS}
For any $K \in \{1, \cdots, N \}$, $\BL_{\Vm_{\W}}(K)$ is a subset of the global normalized neighboring smooth with parameter $C$, when $C \geq  (1 - \lambda^{(\W)}_{K} / |\lambda_{\max}{(\W)}| )^2$.

\label{df:concentrate_v}
A graph signal $\x$ is~\emph{$\epsilon$-vertex concentrated} on a graph vertex set $\Gamma$ when it satisfies
\begin{equation*}
	\left\| \x - \Id_{\Gamma} \x \right\|_2^2 \leq \epsilon,
\end{equation*}
where $\Id_{\Gamma} \in \ensuremath{\mathbb{R}}^{N \times N}$ is a diagonal matrix, with $(\Id_{\Gamma})_{i,i} = 1$ when $i \in \Gamma$ and $0$, otherwise.

\label{df:concentrate_s}
A graph signal $\x$ is~\emph{$\epsilon$-spectrum concentrated} on a graph spectrum band $\Omega$ when it satisfies
\begin{equation*}
	\left\| \x - \Vm_{\Omega} \Um_{\Omega} \x \right\|_2^2 \leq \epsilon,
\end{equation*}
where $ \Vm_{\Omega} \in \ensuremath{\mathbb{R}}^{N \times |\Omega|}$ is a submatrix of $\Vm$ with columns selected by $\Omega$ and $ \Um_{\Omega} \in \ensuremath{\mathbb{R}}^{|\Omega| \times N}$ is a submatrix of $\Vm$ with rows selected by $\Omega$.

({\bf Uncertainty principle of the graph vertex and spectrum domains})
\label{thm:GNNS}
Let a unit norm signal $\x$ supported on an undirected graph  be $\epsilon_{\Gamma}$-vertex concentrated and $\epsilon_{\Omega}$-spectrum concentrated at the same time. Then,
\begin{equation*}
|\Gamma| \cdot |\Omega| \geq  \frac{(1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \Um_{\Omega} \right\|_{\infty}^2 }.
\end{equation*}

 We first show $\left\| \Vm_{\Omega} \Um_{\Omega}  \Id_{\Gamma} \right\|_2 \leq \left\| \Um_{\Omega} \right\|_{\infty}  \sqrt{ |\Gamma|\cdot |\Omega|}$.
\begin{eqnarray*}
&&	( \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma}  \x )_s
\ = \ \sum_{k \in \Omega} \Vm_{s,k} \left( \sum_{i \in \Gamma} \Um_{k,i} x_i \right)
\\
& = &  \sum_{i \in \Gamma}  \left(   \sum_{k \in \Omega} \Vm_{s,k} \Um_{k,i} \right) x_i
\ = \ \sum_i q(s,i) x_i,
\end{eqnarray*}
   where
   \begin{equation*}
	\label{eq:Delta}
	q(s,i) = 
  \left\{ 
    \begin{array}{rl}
      \sum_{k \in \Omega} \Vm_{s,k} \Um_{k,i}, & i \in \Gamma;\\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}
Let $\y^{(i)}$ be a graph signal with $y^{(i)}_s = q(s,i)$. Then, $( \widehat{\y^{(i)}} )_k = {\bf 1}_{k \in \Omega} \Um_{k,i}$. We then have
\begin{eqnarray*}
&&	\left\| \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma}  \right\|_{2}^2
 \ \leq \  \left\| \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma}  \right\|_{\rm HS}^2
\\
& = & \sum_{i \in \Gamma} \sum_{s} |q(s,i)|^2 
\ =  \sum_{i \in \Gamma} \left\| \y^{(i)} \right\|_2^2
\\
& = & \sum_{i \in \Gamma} \left\| \widehat{ \y^{(i)} } \right\|_2^2
\ = \  \sum_{i \in \Gamma} \sum_{k} \left( {\bf 1}_{k \in \Omega} \Um_{k,i} \right)^2
\\
& \leq & \left\| \Um_{\Omega} \right\|_{\infty}^2 \sum_{i \in \Gamma} \sum_{k} {\bf 1}_{k \in \Omega} 
\ = \   \left\| \Um_{\Omega} \right\|_{\infty}^2 |\Gamma| \cdot |\Omega|.
\end{eqnarray*}

We then show that $\left\|  \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma} \x  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} )$.
Based on the assumption, we have
   \begin{eqnarray*}
 &&  \left\| \x - \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma}  \x  \right\|_2
   \\
& = &   \left\| \x - \Id_{\Gamma} \x \right\|_2  + \left\| \Id_{\Gamma} \x -  \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma} \x  \right\|_2 
	\\
& \leq & \epsilon_{\Omega}  +  \epsilon_{\Gamma}. 
   \end{eqnarray*}
Since $\x$ has a unit norm, by the triangle inequality,  we have
   \begin{equation*}
  \left\|  \Vm_{\Omega} \Um_{\Omega} \Id_{\Gamma}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ).
   \end{equation*}
Finally, we combine two results and obtain  
\begin{equation*}
|\Gamma|\cdot |\Omega|  \geq  \frac{\left\| \Vm_{\Omega} \Um_{\Omega}  \Id_{\Gamma} \right\|_2^2}{\left\| \Um_{\Omega} \right\|_{\infty}^2 } \ > \ \frac{  (1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \Um_{\Omega} \right\|_{\infty}^2}
\end{equation*}

